typedef unsigned int size_t;
typedef float rational_t;

void* operator new(size_t, unsigned int, const char*, int);
#define NEW new(0,__PRETTY_FUNCTION__,0)

class entity;
class po;
class vector3d
{
public:
  float x, y, z;
};
class vert;
class cface;
class material;

template <int inst> class __malloc_alloc_template {};

template <class T, class Alloc = __malloc_alloc_template<0> >
class vector
{
public:
  T* start;
  T* finish;
  T* end_of_storage;

  vector& operator=(const vector&);
  int size() const { return finish - start; }
  void _M_insert_aux(T*, const T&);
  void push_back(const T& value)
  {
    if (finish != end_of_storage)
    {
      *finish = value;
      ++finish;
    }
    else
      _M_insert_aux(finish, value);
  }
  T& operator[](int index) { return start[index]; }
  const T& operator[](int index) const { return start[index]; }
};

template <class T>
class instance_bank
{
public:
  T* new_instance(const T&);
};

extern instance_bank<material> material_bank;

class collision_geometry
{
public:
  virtual ~collision_geometry();
  virtual collision_geometry* make_instance(entity*) const = 0;
  virtual void xform(const po&);
  virtual void apply_radius_scale(rational_t);
  virtual void split_xform(const po&, const po&, int);
  virtual void split_xform(const po&, const po&, const po&, int, int);
  virtual rational_t get_radius() const;
  virtual rational_t get_core_radius() const;
  virtual const vector3d& get_abs_position() const;
  virtual void estimate_physical_properties(entity*, rational_t) = 0;
  virtual void get_closest_point_along_dir(vector3d*, const vector3d&) const = 0;
  virtual void get_min_extent(vector3d*) const;
  virtual void get_max_extent(vector3d*) const;
  virtual const vector3d& get_pivot() const;
  virtual unsigned int get_type() const = 0;
  virtual bool is_pivot_valid() const;
  virtual bool is_entity_collision() const;
  virtual bool is_camera_collision() const;

protected:
  entity* owner;
  bool valid;
};

class cg_mesh : public collision_geometry
{
public:
  enum { FLAG_PIVOT_VALID = 0x00000001 };

  cg_mesh();
  virtual ~cg_mesh();
  virtual collision_geometry* make_instance(entity*) const;
  virtual void xform(const po&);
  virtual void split_xform(const po&, const po&, int);
  virtual void split_xform(const po&, const po&, const po&, int, int);
  const material& get_material(short i) const { return *materials[i]; }
  virtual void get_closest_point_along_dir(vector3d*, const vector3d&) const;
  virtual void get_min_extent(vector3d*) const;
  virtual void get_max_extent(vector3d*) const;
  virtual rational_t get_radius() const { return radius; }
  virtual const vector3d& get_pivot() const { return pivot; }
  void set_flag(int flag, bool torf)
  {
    if (torf)
      flags |= flag;
    else
      flags &= (0xFFFFFFFF^flag);
  }
  virtual bool is_pivot_valid() const { return (flags & FLAG_PIVOT_VALID); }
  virtual bool is_entity_collision() const;
  virtual bool is_camera_collision() const;
  virtual unsigned int get_type() const;
  virtual void estimate_physical_properties(entity*, rational_t);

protected:
  vector<vert> raw_verts;
  vector<vert> verts;
  vector<cface> cfaces;
  vector<material*> materials;
  rational_t cface_xmin;
  vector<int> lookup_low;
  vector<int> lookup_high;
  vector3d pivot;
  unsigned int flags;
  int lookup_size;
  rational_t radius;
};

collision_geometry* cg_mesh::make_instance( entity* ent ) const
{
  cg_mesh* newcgmesh = NEW cg_mesh;
  newcgmesh->owner = ent;
  newcgmesh->valid = valid;
  newcgmesh->raw_verts = raw_verts;
  newcgmesh->verts = verts;
  newcgmesh->cfaces = cfaces;
  newcgmesh->cface_xmin = cface_xmin;
  newcgmesh->lookup_low = lookup_low;
  newcgmesh->lookup_high = lookup_high;
  for (int i=0; i<(int)materials.size(); ++i)
  {
    newcgmesh->materials.push_back(material_bank.new_instance(get_material(i)));
  }
  newcgmesh->pivot = pivot;
  newcgmesh->radius = radius;
  newcgmesh->set_flag(FLAG_PIVOT_VALID,is_pivot_valid());
  return newcgmesh;
}
